from unicorn import *
from unicorn.x86_const import *
R=Path(__file__).resolve().parents[1];b=(R/'baseline48/prior/inputs/nite3w - 110.exe').read_bytes();assert hashlib.sha256(b).hexdigest()=='12fe5168783446275802e0e947898261b5eca6b88288f3a895fc1faa4c544481';c=b[0xe8a0:0xe8a0+0x73fe];D=0x10480;u=Uc(UC_ARCH_X86,UC_MODE_16);u.mem_map(0,0x100000);u.mem_write(0x20000,c);end={}
def hook(u,a,n,data):
 if a in [0x23710,0x23746]:end.update(address=a);u.emu_stop()
u.hook_add(UC_HOOK_CODE,hook);counts={'success':0,'overflow':0,'zeroAX':0}
for ax,cx in [(1,x) for x in range(65536)]+[(0,x) for x in [0,1,0xfeff,0xff00,0xff01,65535]]:
 end.clear();marker=b'\xa5'*12;u.mem_write(D+0x82e,marker);u.mem_write(D+0x864,b'\xa5\xa5')
 for reg,v in [(UC_X86_REG_CS,0x2000),(UC_X86_REG_DS,0x1048),(UC_X86_REG_SS,0x4000),(UC_X86_REG_SP,0xd000),(UC_X86_REG_AX,ax),(UC_X86_REG_CX,cx),(UC_X86_REG_SI,0x1234),(UC_X86_REG_DI,0x5678),(UC_X86_REG_BX,0x9abc),(UC_X86_REG_ES,0x3456),(UC_X86_REG_DX,0xdef0),(UC_X86_REG_EFLAGS,2)]:u.reg_write(reg,v)
 u.emu_start(0x23720,0x2f000,count=40)
 success=bool(ax) and cx<0xff00
 assert end['address']==(0x23746 if success else 0x23710)
 expected=struct.pack('<6H',cx+256,0x1234,0x5678,0x9abc,0x3456,0xdef0) if success else marker
 assert bytes(u.mem_read(D+0x82e,12))==expected
 assert bytes(u.mem_read(D+0x864,2))==(b'\x56\x34' if ax else b'\xa5\xa5')
 counts['success' if success else ('overflow' if ax else 'zeroAX')]+=1
rows=[r for r in csv.DictReader(open(R/'baseline48/pass48-results/listing.tsv'),delimiter='\t') if r['address'].startswith('1008:') and 0x3720<=int(r['address'][5:],16)<0x3746]
for r in rows:
 a=int(r['address'][5:],16);assert c[a:a+len(r['bytes'])//2].hex()==r['bytes']
refs=[r for r in csv.DictReader(open(R/'baseline48/pass48-results/references.tsv'),delimiter='\t') if r['to'] in ['1048:082e','1048:08b0','1048:08b2']]
out=dict(cases=65542,counts=counts,range='3720..3742, stop3710 or3746',refs=refs,stubs=[],full_game_runtime=False,limits=['Starts after INITTASK, no real API/register contract','No whole-startup run','SS000A/000C initialization not resolved','Indirect/bulk writes not ruled out'])
(R/'pass61/verification.json').write_text(json.dumps(out,indent=2));(R/'pass61/native_listing.json').write_text(json.dumps(rows,indent=2));print(counts)
